-- 0xNull Executor (Basic UI Script Runner)

local Rayfield = loadstring(game:HttpGet('https://sirius.menu/rayfield'))()

local Window = Rayfield:CreateWindow({
    Name = "0xNull Executor",
    LoadingTitle = "0xNull",
    LoadingSubtitle = "by 0xNull",
    ConfigurationSaving = {
        Enabled = false
    },
    KeySystem = false
})

-- Create Tab
local Tab = Window:CreateTab("Executor", 4483362458)

-- Script Box (stores text)
local ScriptText = ""

Tab:CreateInput({
    Name = "Enter Script",
    PlaceholderText = "print('Hello world')",
    RemoveTextAfterFocusLost = false,
    Callback = function(text)
        ScriptText = text
    end,
})

-- Execute Button
Tab:CreateButton({
    Name = "Execute Script",
    Callback = function()
        local func, err = loadstring(ScriptText)
        if func then
            pcall(func)
        else
            warn("Error: "..err)
        end
    end,
})

-- Clear Button
Tab:CreateButton({
    Name = "Clear Script",
    Callback = function()
        ScriptText = ""
        print("Cleared")
    end,
})

-- Example scripts
Tab:CreateButton({
    Name = "Print Hello",
    Callback = function()
        print("Hello from 0xNull")
    end,
})

Tab:CreateButton({
    Name = "Give WalkSpeed",
    Callback = function()
        game.Players.LocalPlayer.Character.Humanoid.WalkSpeed = 50
    end,
})

Tab:CreateButton({
    Name = "Reset WalkSpeed",
    Callback = function()
        game.Players.LocalPlayer.Character.Humanoid.WalkSpeed = 16
    end,
})

Rayfield:LoadConfiguration()
